		CarrierUpdateFilterData GetUpdateFilterData()
		{
			var data = new CarrierUpdateFilterData();
			var mostInterestingTransport = Consol.Transports.MostInterestingTransport;
			if (mostInterestingTransport != null)
			{
				data.startDate = !mostInterestingTransport.JW_ATD.IsEmpty ? mostInterestingTransport.JW_ATD : mostInterestingTransport.JW_ETD;
				data.expiryDate = data.startDate;
			}

			data.serviceProviderPK = Consol.ShippingLine?.PK ?? ZGuid.Empty;
			data.contractID = Consol.JK_CarrierContractNumber;
			data.transportMode = Consol.JK_TransportMode;

			return data;
		}
