		#region Transport Mode

		void ToggleControlsBasedOnTransportMode(string selectedItem)
		{
			if (ConsolIsAir)
			{
				CharterPanel.Visible = ConsolIsCharter(selectedItem) && !ConsolIsCourier(selectedItem);
				AirConsolPanel.Visible = !ConsolIsCharter(selectedItem) && !ConsolIsCourier(selectedItem);
				ConsolChargeableRateCalcEdit.Visible = true;
				SpecialHandlingUserControl.Visible = true;
				SecurityStatusDropEdit.Visible = true;
				ChargesApply.Visible = true;
				AWBDimsDropEdit.Visible = true;
			}
			else
			{
				AirConsolPanel.Visible = false;
				CharterPanel.Visible = false;
				ConsolChargeableRateCalcEdit.Visible = false;
				SpecialHandlingUserControl.Visible = false;
				SecurityStatusDropEdit.Visible = false;
				ChargesApply.Visible = false;
				AWBDimsDropEdit.Visible = false;
			}
			CRNPanelSea.Visible = !ConsolIsAir || ConsolIsCourier(selectedItem);

			if (ConsolIsSea)
			{
				MasterBillIssueDateEdit.Location = ControlDpiScalingHelper.NewScaledPoint(270, 76, true);

				if (FreightDataRegistry.Instance.EnableBoleroEBLIntegration.Value.EnableEBLIntegration)
				{
					LatestStatusGroupBox.Location = CargoWise.Windows.UI.ControlDpiScalingHelper.NewScaledPoint(15, 120, true);
					LatestStatusGroupBox.Size = CargoWise.Windows.UI.ControlDpiScalingHelper.NewScaledSize(550, 100, true);
				}
				else
				{
					LatestStatusGroupBox.Location = CargoWise.Windows.UI.ControlDpiScalingHelper.NewScaledPoint(15, 124, true);
					LatestStatusGroupBox.Size = CargoWise.Windows.UI.ControlDpiScalingHelper.NewScaledSize(470, 80, true);
				}
			}
			else
			{
				MasterBillIssueDateEdit.Location = ControlDpiScalingHelper.NewScaledPoint(358, 76, true);
			}

			DocsTabPage.RunWhenBindingOrFirstShown(delegate
			{
				MasterBillIssueDateEdit.Visible = ConsolIsAir || ConsolIsSea || (Consol.IsRoad && GlbCompany.CurrentCompany.GC_RN_NKCountryCode.Equals(Constants.CountryCodes.SouthAfrica));
				JK_RL_NKMasterBillIssuePlaceFindBox.Visible = ConsolIsSea;
				PackageGroupingDropEdit.Visible = ConsolIsSea && FreightDataRegistry.Instance.EnablePackageGrouping.Value;
				LatestStatusGroupBox.Visible = ConsolIsSea;
				CarrierBookingOfficeCodeFindBox.Visible = ConsolIsSea;
				BillOfLadingBillStatusDropEdit.Visible = ConsolIsSea && FreightDataRegistry.Instance.EnableBoleroEBLIntegration.Value.EnableEBLIntegration;
				BillOfLadingBillDateDateEdit.Visible = ConsolIsSea && FreightDataRegistry.Instance.EnableBoleroEBLIntegration.Value.EnableEBLIntegration;
				BillOfLadingBillTypeDropEdit.Visible = ConsolIsSea && FreightDataRegistry.Instance.EnableBoleroEBLIntegration.Value.EnableEBLIntegration;
				BillOfLadingBillTermsDropEdit.Visible = ConsolIsSea && FreightDataRegistry.Instance.EnableBoleroEBLIntegration.Value.EnableEBLIntegration;
				ElectronicBillOfLadingReferenceTextBox.Visible = !Consol.JK_ElectronicBillOfLadingReference.IsEmpty && ConsolIsSea && FreightDataRegistry.Instance.EnableBoleroEBLIntegration.Value.EnableEBLIntegration;
				ViewEBLButton.Visible = !Consol.JK_ElectronicBillOfLadingReference.IsEmpty && ConsolIsSea && FreightDataRegistry.Instance.EnableBoleroEBLIntegration.Value.EnableEBLIntegration;
			});

			ChangeLoadingMetersVisibility();
		}

