		[System.Diagnostics.CodeAnalysis.SuppressMessage("CargoWiseOne", "CW1046", Justification = "Controls are not buttons")]
		void ChangeLabelAndCaptionResourceString()
		{
			if ((Consol?.IsCoLoad ?? false) && (Consol?.IsSendingOrReceivingForwarderGateway ?? false))
			{
				var gatewayCoLoadCaptionResourceString = Res.GetData("691ce53b-eefc-4adc-81e5-b574f8ad9a94", "Co-Load With", "Enter the Coload Agent if the Consol Type is a Gateway Co-Load. A co loader is a forwarder that you use if your organization has chosen not to cut their own direct bill or consol.");
				JK_OA_CreditorAddressControl.GetExtension<ILabelCaptionRenderer>().Caption = gatewayCoLoadCaptionResourceString.Caption;
				JK_OA_CreditorAddressControl.CaptionResourceString = gatewayCoLoadCaptionResourceString;
			}
			else if (Consol?.IsCoLoad ?? false)
			{
				var coLoadCaptionResourceString = Res.GetData("26aeb339-d00f-4272-b8e7-079a38215613", "Co-Load With", "Enter the Coload Agent if the Consol Type is a Co-Load. A co loader is a forwarder that you use if your organization has chosen not to cut their own direct bill or consol.");
				JK_OA_CreditorAddressControl.GetExtension<ILabelCaptionRenderer>().Caption = coLoadCaptionResourceString.Caption;
				JK_OA_CreditorAddressControl.CaptionResourceString = coLoadCaptionResourceString;
			}
			else
			{
				var creditorCaptionResourceString = Res.GetData("8b750c0d-c6a8-4b5a-ae94-879be2dc5b06", "Creditor", "The party who is the Creditor for the transportation costs associated with this consolidation. Usually this is the Carrier, their Agent or a Gateway.");
				JK_OA_CreditorAddressControl.GetExtension<ILabelCaptionRenderer>().Caption = creditorCaptionResourceString.Caption;
				JK_OA_CreditorAddressControl.CaptionResourceString = creditorCaptionResourceString;
			}

			if (Consol != null)
			{
				JK_Calc_ActualVolumeWeightEdit.GetExtension<ILabelCaptionRenderer>().Caption = ConsolActualVolumeWeightLabel;

				var summary = ConsolActualVolumeWeightHint;
				JK_Calc_ActualVolumeWeightEdit.GetExtension<IHintExtension>().Description = summary;
				ToolTipService.SetToolTip(JK_Calc_ActualVolumeWeightEdit, summary);
				UpdateExcessWeightLabels();
			}
		}

		string ConsolActualVolumeWeightLabel
		{
			get
			{
				return Consol.IsConsolChargeableByWeight
					? Res.GetString("2c3bc23a-875d-4471-b5fe-7f8cb167ccc3", "Vol. Weight")
					: Res.GetString("4ab23680-f289-41c3-abe4-c4635b697cd9", "Weight Vol.");
			}
		}

		string ConsolActualVolumeWeightHint
		{
			get
			{
				var factor = Consol.GetConsolConversionFactor();
				if (factor.IsEmpty)
				{
					return string.Empty;
				}

				var currentUnit = factor.DenominatorMeasureType.ToString();

				return Res.GetString("b2078a11-1823-11e7-837d-fcaa14295823", "{0}, Considering {1}",
					currentUnit == "Volume"
					? "Weight converted to volume"
					: "Volume converted to weight"
					, factor.ToLongString());
			}
		}

		string ConsolExcessVolumeWeightLabel
		{
			get
			{
				if (Consol.IsConsolChargeableByWeight)
				{
					return Consol.Density.IsActualExcess
						? Res.GetString("28dbdd84-de4f-4214-87d9-7059af33291f", "Excess Actual Wgt.")
						: Res.GetString("300c1b9b-efda-4166-8308-dc7d1d12331e", "Excess Vol. Wgt.");
				}

				return Consol.Density.IsActualExcess
					? Res.GetString("190b2af2-2c0b-4d7e-8e2d-0ae2f596e332", "Excess Actual Vol.")
					: Res.GetString("bae7bff2-9473-4b79-8cd3-15526b001513", "Excess Wgt. Vol.");
			}
		}

		void ToggleControlsVisibilityBasedOnAgentType()
		{
			var mawbControls = new Control[]
				{
					AirlinePrefixTextBox,
					MAWBNumberTextBox,
					MAWBHyphenLabel,
					IsNeutralCheckBox
				};

			var shipmentDetailsControls = new Control[]
				{
					ShipmentDetailsBottomPanel,
					ShipmentModuleButtonGrid
				};

			var colodConsolsControls = new Control[]
				{
					ConsolDetailsBottomPanel,
					ColoadConsolModuleButtonGrid
				};

			var coLoadConsolsMBLAndBkgRefControls = new Control[]
				{
					JK_CoLoadMasterBillBoundTextEdit,
					JK_CoLoadBookingReferenceBoundTextEdit
				};

			bool isMultiAWBMaster = Consol != null && Consol.IsMultiAWBMaster;
			var isCoLoadConsol = Consol != null && Consol.IsCoLoad;

			Array.ForEach(mawbControls, control => control.Visible = !isMultiAWBMaster);
			Array.ForEach(shipmentDetailsControls, control => control.Visible = !isMultiAWBMaster);
			Array.ForEach(colodConsolsControls, control => control.Visible = isMultiAWBMaster);
			Array.ForEach(coLoadConsolsMBLAndBkgRefControls, control => control.Visible = isCoLoadConsol);
		}

