		#region Mode Booleans

		bool ConsolIsAir
		{
			get { return Consol != null && Consol.IsAir; }
		}

		bool ConsolIsSea
		{
			get { return Consol != null && Consol.IsSea; }
		}

		bool ConsolIsCharter(string overrideValue)
		{
			return !string.IsNullOrEmpty(overrideValue)
				? overrideValue == Constants.AgentType.Charter
				: Consol != null && Consol.IsCharter;
		}

		bool ConsolIsCourier(string overrideValue)
		{
			return !string.IsNullOrEmpty(overrideValue)
				? overrideValue == Constants.AgentType.Courier
				: Consol != null && Consol.IsCourier;
		}

		#endregion

		#region ToggleDateTimeFormat

		void ToggleDateTimeFormat()
		{
			if (ShipmentModuleButtonGrid.InnerGrid.TableStyles.Count > 0)
			{
				foreach (ZGridColumnStyle columnStyle in ShipmentModuleButtonGrid.InnerGrid.TableStyles[0].GridColumnStyles)
				{
					var zDateEditColumnStyle = columnStyle as ZDateEditColumnStyle;
					if (zDateEditColumnStyle != null)
					{
						zDateEditColumnStyle.DateTimeFormat = FormatTypeForColumn(columnStyle.MappingName, zDateEditColumnStyle.DateTimeFormat);
					}
				}
			}
			else
			{
				foreach (ZGridColumnInfo columnInfo in ShipmentModuleButtonGrid.InnerGrid.ColumnStyles)
				{
					var zDateEditColumnStyleInfo = columnInfo as ZDateEditColumnStyleInfo;
					if (zDateEditColumnStyleInfo != null)
					{
						zDateEditColumnStyleInfo.DateTimeFormat = FormatTypeForColumn(columnInfo.ColumnName, zDateEditColumnStyleInfo.DateTimeFormat);
					}
				}
			}

			ShipmentModuleButtonGrid.InnerGrid.Invalidate();

			if (Consol != null)
			{
				MasterBillIssueDateEdit.DateTimeFormat = ConsolIsAir ? ZDateTimePickerFormat.Long : ZDateTimePickerFormat.Short;
			}
		}

		ZDateTimePickerFormat FormatTypeForColumn(string columnName, ZDateTimePickerFormat defaultFormat)
		{
			if (columnName == JobShipmentSchema.Constants.JS_E_ARV
				|| columnName == JobShipmentSchema.Constants.JS_E_DEP)
			{
				return ConsolIsSea ? ZDateTimePickerFormat.Short : ZDateTimePickerFormat.Long;
			}

			return defaultFormat;
		}

		#endregion

