		#region View Measurements

		void ViewMeasurements()
		{
			var selectedShipments = ShipmentModuleButtonGrid.InnerGrid.GetSelectedElements<ForwardingShipment>();
			if (selectedShipments.Length == 0)
			{
				Globals.Message.Show(Res.GetString("3bc799f5-9c0e-f698-4b46-05794cf92987", "Please select a shipment."),
					Res.GetString("7c87de3a-cecf-a68a-4377-243f32af2c16", "Select Shipment"), MessageBoxButtons.OK, MessageBoxIcon.Warning);
			}
			else if (Consol.HasChanges || selectedShipments.Any(s => s.HasChanges))
			{
				Globals.Message.Show(Res.GetString("d37844ad-1fbf-8abf-4ad9-ddf7272a6d2c", "Please save before viewing measurements."),
					Res.GetString("5d68d384-d1e1-b48d-4b91-e5d6998c4c58", "Show Measurement"), MessageBoxButtons.OK, MessageBoxIcon.Warning);
			}
			else
			{
				var title = Res.GetString("b6739d09-442e-08b7-4c42-936d951a7883", "View Measurements");
				var shipmentMeasurementDescription = ShipmentMeasurementsHelper.GetMeasurements(selectedShipments);
				ShipmentViewMeasurementsForm.ShowDialog(title, shipmentMeasurementDescription);
			}
		}

		#endregion

