		void ViewShipmentTracking()
		{
			var selectedShipments = ShipmentModuleButtonGrid.InnerGrid.GetSelectedElements<ForwardingShipment>();
			if (selectedShipments.Length == 0)
			{
				Globals.Message.Show(Res.GetString("c3bd087a-239c-4b08-a035-d2c389224536", "Please select a shipment."),
					Res.GetString("9beea25a-605f-4e36-9396-ee905ffe4f53", "Select Shipment"), MessageBoxButtons.OK, MessageBoxIcon.Warning);
			}
			else if (selectedShipments.Length > 10)
			{
				Globals.Message.Show(Res.GetString("9c2c679e-70f1-4d48-9f3c-949f7f0525fb", "Please select a maximum of 10 shipments."),
					Res.GetString("4a541dcd-49d2-4861-ad8e-0a1b00a0f96b", "Select Shipment"), MessageBoxButtons.OK, MessageBoxIcon.Warning);
			}
			else
			{
