		#region Combine Shipments

		void CombineShipmentMenuItem_Click(object sender, EventArgs e)
		{
			CommonShipment[] selectedShipments = ShipmentModuleButtonGrid.InnerGrid.GetSelectedElements<CommonShipment>();
			if (selectedShipments.Length == 0)
			{
				Globals.Message.Show(Res.GetString("ce47f223-4143-4236-92ab-d8c39ad81e35", "Please select a shipment."),
					Res.GetString("52d7d737-e492-4ead-aaf8-d506554ce187", "Select Shipment"), MessageBoxButtons.OK, MessageBoxIcon.Warning);
			}
			else if (Consol.HasChanges || Array.Exists<BusinessObject>(selectedShipments, x => x.HasChanges))
			{
				ShowCantCombineMessage(Res.GetString("7ad6799d-0a3f-4a6a-aa19-023b98f0cf9e", "Please save before combining shipments."));
			}
			else
			{
				CombineShipmentsHelper combineHelper = new CombineShipmentsHelper(selectedShipments[0], Consol);
				if (combineHelper.ShipmentCanBeCombined())
				{
					if (combineHelper.ShipmentHasSiblings)
					{
						CombineShipmentsForm combineForm = new CombineShipmentsForm(combineHelper);
						ZFormModaliser.Show(combineForm, FindForm());
					}
					else
					{
						ShowCantCombineMessage(Res.GetString("246933c9-799c-407d-b5f6-29a3af50c818", "Shipment does not have any matching shipments to combine with.\r\n\r\nEither there are no shipments with the same Consignee/Consignor, or shipments with the same Consignee/Consignor are split, part of a Buyer's Consol or Co-load, or have already been invoiced."));
					}
				}
				else
				{
					ShowCantCombineMessage(Res.GetString("03dd4cd5-5c06-46e0-84f8-698d250c0ae7", "Shipment cannot be combined with other shipments.\r\nIt may be split, part of a Buyer's Consol or Co-load, may have already been invoiced,\r\nor may not contain enough details (Consignee/Consignor)."));
				}
			}
		}

		void ShowCantCombineMessage(string message)
		{
			Globals.Message.Show(message, Res.GetString("fac74a00-e295-4330-9111-30dcdca14af6", "Combine Shipment"), MessageBoxButtons.OK, MessageBoxIcon.Warning);
		}

