		#region Carrier Consortium

		class OrgMenuItem : MenuItem
		{
			public OrgMenuItem(OrgHeader member)
			{
				this.Member = member;
				Text = string.Format(CultureInfo.InvariantCulture, "{0} ({1})", member.OH_FullNameTruncated, member.OH_Code);
			}

			public readonly OrgHeader Member;
		}

		void ButtonSelectFromConsortium_Click(object sender, EventArgs e)
		{
			RefVessel vessel = Consol.Vessel;
			RefCarrierConsortium consortium = (vessel == null ? null : vessel.CarrierConsortium);

			if (consortium != null)
			{
				if (contextMenu != null)
				{
					contextMenu.Dispose();
				}

				contextMenu = new ContextMenu();
				foreach (var member in consortium.OrgHeaders)
				{
					var menu = new OrgMenuItem(member);
					menu.Click += delegate
					{
						Consol.SetDefaultShippingLineAddress(menu.Member);
					};
					contextMenu.MenuItems.Add(menu);
				}

				contextMenu.Show(ButtonSelectFromConsortium, ControlDpiScalingHelper.NewScaledPoint(0, ButtonSelectFromConsortium.Height, false));
			}
			else
			{
				Globals.Message.Show(Res.GetString("ca9e6455-019c-49f7-92d4-e01c5bbe1517", "The vessel does not belong to a consortium."),
					Res.GetString("1003874a-a69a-4442-9e0c-3f3057a74612", "Select Carrier From Consortium."), MessageBoxButtons.OK, MessageBoxIcon.Warning);
			}
		}

		ContextMenu contextMenu;

