		#region SplitBookingReferenceIfRequired

		void SplitBookingReferenceIfRequired()
		{
			if (Consol != null && Consol.ReferenceNumberShouldBeSplitIntoNumbers(Consol.JK_BookingReference))
			{
				var message = Res.GetString("65F9DE69-9D28-4BAA-833B-6BFA4DB345AF", @"Multiple Carrier Booking References have been detected.
We will automatically split them and add them to the Reference Numbers grid under the Numbers tab.");
				var caption = Res.GetString("7FBB84F2-16F1-4D09-89A6-5AB65C76A76A", "Booking Reference");
				if (Globals.Message.Show(message, caption, MessageBoxButtons.OKCancel, MessageBoxIcon.Information, DialogResult.OK) == DialogResult.OK)
				{
					Consol.SplitBookingReferenceNumbersIntoAdditionalReferenceCollection();
				}
			}
		}

