		#region Carrier Contracts

		void ToggleControlsBasedOnCarrierContractRegistry()
		{
			// For customers with both Contracts and Allocations enabled, we use the find box with the simulation GUI
			// For customers with only Contracts enabled, legacy webview2 lookup button is used
			// For customers with neither, only the textbox without the lookup button is used

			var carrierAndClientContractModulesAreEnabled = ObjectFactory.Get<IContractPermissions>().IsCarrierAndClientContractModulesEnabled();
			var allocationsAreEnabled = ContractsPermissions.IsAllocationsVisible();

			JK_RCA_AllocationRouteCodeFindBox.Visible = allocationsAreEnabled;
			JK_CarrierContractNumberFindBox.Visible = allocationsAreEnabled;

			JK_CarrierContractNumberBoundTextEdit.Visible = !allocationsAreEnabled;
			CarrierContractImportButton.Visible = carrierAndClientContractModulesAreEnabled && !allocationsAreEnabled;
		}

